# Check what demos we actually have for this task by checking the session logs
import os, re, json

d = os.environ['RLM_SESSION_DIR']
sessions_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'

print(f"Session log: {sessions_file}")

# Find demo pair messages
with open(sessions_file, 'r') as f:
    lines = f.readlines()

demo_input = None
demo_output = None

for line in lines:
    if 'Demo pair' in line:
        # Parse demo pair info
        match = re.search(r'Demo pair .* \((\d+)x(\d+)\):\s*(.+?)\(\d+ of \d+\)', line, re.DOTALL)
        if match:
            h, w = int(match.group(1)), int(match.group(2))
            grid_text = match.group(3)
            if demo_input is None:
                demo_input = [grid_text[:h].split()]
            elif demo_output is None:
                demo_output = [grid_text[h:].split()]

if demo_input:
    demo_input = [[int(x) for x in row] for row in demo_input]
if demo_output:
    demo_output = [[int(x) for x in row] for row in demo_output]

print(f"\nDemo input shape: {len(demo_input) if demo_input else 0}x{len(demo_input[0]) if demo_input else 0}")
print(f"Demo output shape: {len(demo_output) if demo_output else 0}x{len(demo_output[0]) if demo_output else 0}")

if demo_input:
    for i, row in enumerate(demo_input):
        print(f"Input row {i}: {row}")

print("\n--- Demo Output ---")
if demo_output:
    for i, row in enumerate(demo_output):
        print(f"Output row {i}: {row}")

